#include "source_bsp_inline_brush_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("usage: test_source_bsp_inline_brush map.bsp");auto bsp=readBinaryAssetCandidate(argv[1]);auto brush=readSourceBspInlineBrushCandidate(bsp,16);std::cout<<"extracted_vertices="<<brush.positions.size()<<" triangles="<<brush.triangles.size()<<" materials="<<brush.materials.size();for(auto&m:brush.materials)std::cout<<" material_name="<<m;std::cout<<"\n";if(brush.positions.size()!=8||brush.uvs.size()!=8||brush.normals.size()!=8||brush.triangles.size()!=4||brush.materials.size()!=1)throw std::runtime_error("mtt_soldier *17 extraction mismatch");for(size_t i=0;i<brush.positions.size();++i){for(float v:brush.positions[i])if(!std::isfinite(v))throw std::runtime_error("nonfinite brush position");for(float v:brush.normals[i])if(!std::isfinite(v))throw std::runtime_error("nonfinite brush normal");for(float v:brush.uvs[i])if(!std::isfinite(v))throw std::runtime_error("nonfinite brush UV");}for(auto&t:brush.triangles)for(auto i:t.vertices)if(i>=brush.positions.size()||t.material>=brush.materials.size())throw std::runtime_error("brush triangle index");std::cout<<"inline_brush_model=17 faces=2 vertices="<<brush.positions.size()<<" triangles="<<brush.triangles.size()<<" material="<<brush.materials[0]<<" uv_finite=1 normals_finite=1 topology_checked=1 world_transform_applied=0\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
